var lifeColor = new Uint8Array([255, 255, 255, 255]);
var n = 500;
var grid;
var zoom;

setup = () => {
  const m = max(windowWidth, windowHeight);
  createCanvas(m, m);
  zoom = m / n;
  pg = createGraphics(n, n);
  pg.pixelDensity(1);
	initialize();
};

initialize = () =>{
  pg.background('black');
  pg.loadPixels();
	grid = new Uint8Array(n * n);
};

draw = () => {
  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    const x = 0 | ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / zoom);
    const y = 0 | ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / zoom);
    const i = x + n * y;
    grid[i] = 1;
    pg.pixels.set(lifeColor, i*4);
  }

  const next = new Uint8Array(grid);
  for (let y = 1; y < n - 1; y++) {
    for (let x = 1; x < n - 1; x++) {
      const i = x + y * n;
      if (grid[i]) {
        let pi = i * 4;
        pg.pixels[pi]   = (pg.pixels[pi] + 2) & 0xff;
        pg.pixels[++pi] = (pg.pixels[pi] + 5) & 0xff;
        pg.pixels[++pi] = (pg.pixels[pi] + 12) & 0xff;
      } else {
        const sum =
          grid[i - 1 - n] +
          grid[i - 1] +
          grid[i - 1 + n] +
          grid[i - n] +
          grid[i + n] +
          grid[i + 1 - n] +
          grid[i + 1] +
          grid[i + 1 + n];
        if (sum == neighbors) {
          const i = x + y * n;
          next[i] = 1;
          pg.pixels.set(lifeColor, i * 4);
        }
      }
    }
  }
  grid = next;
  pg.updatePixels();
  image(pg, 0, 0, width, height);
};

